parameters.functionCode:
const stats = $input.first().json;

const cleanupTasks = [];

// Audit logs older than 90 days
if (stats.old_audit_logs > 0) {
  cleanupTasks.push({
    table: 'audit_logs',
    condition: "created_at < NOW() - INTERVAL '90 days'",
    estimated_rows: stats.old_audit_logs,
    description: 'Remove audit logs older than 90 days'
  });
}

// Execution stats older than 30 days
if (stats.old_exec_stats > 0) {
  cleanupTasks.push({
    table: 'workflow_execution_stats',
    condition: "started_at < NOW() - INTERVAL '30 days' AND status = 'success'",
    estimated_rows: stats.old_exec_stats,
    description: 'Remove successful execution stats older than 30 days'
  });
}

// Expired rate limits
if (stats.expired_rate_limits > 0) {
  cleanupTasks.push({
    table: 'rate_limits',
    condition: "window_start < NOW() - INTERVAL '24 hours'",
    estimated_rows: stats.expired_rate_limits,
    description: 'Remove expired rate limit windows'
  });
}

// Old health checks
if (stats.old_health_checks > 0) {
  cleanupTasks.push({
    table: 'system_health',
    condition: "checked_at < NOW() - INTERVAL '7 days'",
    estimated_rows: stats.old_health_checks,
    description: 'Remove health checks older than 7 days'
  });
}

// Old keyword rankings (keep 1 year)
if (stats.old_rankings > 0) {
  cleanupTasks.push({
    table: 'keyword_rankings',
    condition: "checked_at < NOW() - INTERVAL '365 days'",
    estimated_rows: stats.old_rankings,
    description: 'Remove keyword rankings older than 1 year'
  });
}

return [{
  json: {
    db_size_mb: Math.round(stats.db_size_bytes / 1024 / 1024),
    total_audit_logs: stats.total_audit_logs,
    total_exec_stats: stats.total_exec_stats,
    cleanup_tasks: cleanupTasks,
    total_rows_to_clean: cleanupTasks.reduce((sum, t) => sum + t.estimated_rows, 0)
  }
}];

